package main

import (
  "fmt"
  "os"
)

func main() {
  pass := 0
  fail := 0
  for _, c := range [][2]string{
    {CleanPath(""), "/"},
    {CleanPath("/"), "/"},
    {CleanPath("a"), "/a"},
    {CleanPath("./"), "/"},
    {CleanPath("../"), "/"},
    {CleanPath("/.."), "/"},
    {CleanPath("/../"), "/"},
    {CleanPath("/../a"), "/a"},
    {CleanPath("/a/.."), "/"},
    {CleanPath("/a/../.."), "/"},
    {CleanPath("/a/../../"), "/"},
    {CleanPath("/a/../../b"), "/b"},
    {CleanPath("/a/../../b/"), "/b/"},
    {CleanPath("/a/b/../../c"), "/c"},
    {CleanPath("/a/./b/../c"), "/a/c"},
    {CleanPath("a/../../b"), "/b"},
    {CleanPath("/a/../../b/../../c"), "/c"},
    {Normalize("/a/./b/?x=1"), "/a/b/"},
    {Normalize("?x=1"), "/"},
    {Normalize("a?b"), "/a"},
    {Normalize("/..?x"), "/"},
    {Normalize("//a//b"), "/a/b"},
    {Normalize("/a/../../b/"), "/b/"},
    {Normalize("../../../"), "/"},
  } {
    if c[0] == c[1] {
      pass++
    } else {
      fail++
      fmt.Fprintln(os.Stderr, "got", c[0], "want", c[1])
    }
  }
  fmt.Printf("TESTS %d %d\n", pass, fail)
  if fail > 0 {
    os.Exit(1)
  }
}
